/// Contract class <c>METAPBulkUpdateContract</c> to maintain all parameters required
/// </summary>
[   
    DataContract,
    SysOperationContractProcessing(classStr(METBulkUpdateUIBuilder))
]
class METBulkUpdateContract 
{
    container       storageResult;
    NoYes           dueDate, onHold;

}

