/// <summary>
/// Parameter method which holds values of the packed variables from <c>FileUploadTemporaryStorageResult</c> class
/// </summary>
/// <param name = "_storageResult">Packed instance of <c>FileUploadTemporaryStorageResult</c> class</param>
/// <returns>Container with packed values</returns>
[DataMemberAttribute('StorageResult')]
public container parmStorageResult(container _storageResult =  storageResult)
{
    storageResult = _storageResult;
    return storageResult;
}

/// <summary>
/// Parameter for due date functionality
/// </summary>
/// <param name = "_dueDate">to modify due date or not</param>
/// <returns>yes or no</returns>
[DataMemberAttribute('DueDate')]
public NoYes parmDueDate(NoYes _dueDate =  dueDate)
{
    dueDate = _dueDate;
    return dueDate;
}

/// <summary>
/// Parameter for on hold functionality
/// </summary>
/// <param name = "_onHold">to modify respective fields if value is no or yes</param>
/// <returns>yes or no</returns>
[DataMemberAttribute('OnHold')]
public NoYes parmOnHold(NoYes _onHold =  onHold)
{
    onHold = _onHold;
    return onHold;
}
